<script setup>
import {computed,ref} from 'vue';
import {wbProductImages,wbImageProxy} from '../../../src/shared/wb-product-images.js';
const props=defineProps({card:{type:Object,required:true}}),visible=ref(false);
const photos=computed(()=>wbProductImages(props.card)),previews=computed(()=>photos.value.map(photo=>wbImageProxy(photo.original)));
</script>
<template><div class="wb-product-images"><el-image v-if="photos.length" :src="wbImageProxy(photos[0].thumbnail)" :preview-src-list="previews" preview-teleported fit="cover" class="wb-product-thumb"><template #error><button type="button" class="image-error" @click.stop="visible=true">查看图片</button></template></el-image><div v-else class="wb-product-thumb image-empty">无图</div><el-button v-if="photos.length" link type="primary" size="small" @click="visible=true">全部 {{photos.length}} 张</el-button>
<el-dialog v-if="visible" v-model="visible" title="商品图片" width="min(880px,95vw)" append-to-body destroy-on-close><div class="wb-photo-grid"><div v-for="(photo,index) in photos" :key="photo.original"><el-image :src="wbImageProxy(photo.thumbnail)" :preview-src-list="previews" :initial-index="index" preview-teleported fit="contain"><template #error><span>图片读取失败，请稍后重试</span></template></el-image><small>{{index===0?'主图':`图片 ${index+1}`}}</small></div></div></el-dialog></div></template>
<style scoped>.wb-product-images{width:74px;flex:none;display:flex;flex-direction:column;align-items:center;gap:4px}.wb-product-thumb{width:64px;height:84px;border-radius:4px}.image-empty,.image-error{display:flex;align-items:center;justify-content:center;background:var(--el-fill-color-light);color:var(--el-text-color-secondary);font-size:12px}.image-error{width:100%;height:100%;border:0;cursor:pointer}.wb-photo-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:12px}.wb-photo-grid>div{display:flex;flex-direction:column;gap:6px;text-align:center}.wb-photo-grid .el-image{width:100%;height:180px;background:var(--el-fill-color-light)}</style>
